\pset footer off
select column_name, count(*) from (select table_name, column_name from information_schema.columns where table_schema='recovery' and table_name in (select object_name from recovery.sys_objects) except select object_name, field_name from recovery.sys_fields) x group by 1 order by 2 desc;
-- Appendix B
with b(t,oldc,newc) as (values ('recovery_case','primary_customer_id','primary_person_key'),('case_account','account_id','account_key'),('case_party','party_id','person_key'),('notice','party_id','person_key'),('listing','asset_id','asset_key'),('asset_sale','asset_id','asset_key'),('debt_sale_account','account_id','account_key'),('interaction','party_id','person_key'),('interaction','contact_point_id','contact_key'),('document','party_id','person_key'),('proceeds','account_payment_id','payment_code'),('case_list_row','account_id','account_key'),('case_entry_exclusion','account_id','account_key'),('signature_request','party_id','person_key'))
select b.t, b.newc, exists(select 1 from information_schema.columns c where c.table_schema='recovery' and c.table_name=b.t and c.column_name=b.newc) has_new, exists(select 1 from information_schema.columns c where c.table_schema='recovery' and c.table_name=b.t and c.column_name=b.oldc) has_old, (select data_type||coalesce('('||character_maximum_length||')','') from information_schema.columns c where c.table_schema='recovery' and c.table_name=b.t and c.column_name=b.newc) typ, exists(select 1 from recovery.sys_fields f where f.object_name=b.t and f.field_name=b.newc) in_dict, exists(select 1 from recovery.sys_fields f where f.object_name=b.t and f.field_name=b.oldc) old_in_dict from b;
select 'removed tables present', string_agg(relname, ',') from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='recovery' and relname in ('loan_account','account_payment','party','contact_point','collateral','account_collateral','collections_history','party_product','valuation','score','asset','load_run','dq_exception','dq_rule','source_field_map','source_code_map','interface_run','interface_signoff','tracker_inventory','tracker_row');
select 'removed in sys_objects/fields', (select count(*) from recovery.sys_objects where object_name in ('loan_account','account_payment','party','contact_point','collateral','account_collateral','collections_history','party_product','valuation','score','asset','load_run','dq_exception','dq_rule','source_field_map','source_code_map','interface_run','interface_signoff','tracker_inventory','tracker_row')), (select count(*) from recovery.sys_fields where references_object in ('loan_account','account_payment','party','contact_point','collateral','account_collateral','collections_history','party_product','valuation','score','asset','load_run','dq_exception','interface_run','tracker_row'));
select 'retained kept', string_agg(relname, ',') from pg_class where relname in ('interface_config','data_product_load','reconciliation_result') and relnamespace='recovery'::regnamespace;
select 'removed cols', string_agg(table_name||'.'||column_name, ',') from information_schema.columns where table_schema='recovery' and ((table_name='role' and column_name like '%entra%') or column_name like '%token%');
